# -*- coding: utf-8 -*-
from pathlib import Path
import json,re
R=Path.cwd();H=R/'docs/professor-20261101';H.mkdir(exist_ok=True)
b=json.loads((R/'docs/checks/publication-20261101/baseline.json').read_text());root='https://yanisken9.github.io/organic-nomenclature-3/'
links={'report':root+'docs/professor-20261101/update.html','welcome':root+'design/welcome-proposal.html?v=release-20261101','viewer':root+'mulermoc-nom-52.html?v=release-20261101','fullCheckpoint':'https://github.com/yanisken9/organic-nomenclature-3/tree/'+b['checkpointBranch']}
style=re.search(r'<style>(.*?)</style>',(R/'docs/professor-20261031/update.html').read_text(),re.S)[1]
body='''<h1>Namelecule — Συνολική αναφορά εργασιών</h1>
<p>Από Παρασκευή 30 Οκτωβρίου, μεσημέρι, έως Κυριακή 1 Νοεμβρίου 2026<br>Γιάννης Σκένδρος · Κύρια έκδοση v52</p>
<nav><a href="WELCOME">Άνοιγμα ενημερωμένου Namelecule</a><a href="VIEWER">Ελεύθερη εξερεύνηση μορίων</a></nav>
<p>Η αναφορά συγκεντρώνει την εργασία της Παρασκευής στα αλκάνια, τις χθεσινές διορθώσεις των γραμμάτων 2D και του συγκεκριμένου κύκλου ζωής JSmol, καθώς και τις επόμενες προσαρμογές έως τους εστέρες. Αντικαθιστά, για την παρούσα ενημέρωση, την αποστολή χωριστών αναφορών 30/10 και 31/10. Όπου οι καταγραφές δεν έχουν ακριβή ώρα, δεν αποδίδεται αυθαίρετη ωριαία χρονολόγηση.</p>
<p><b>Παραμένουν 141 μόρια, 14 ενεργά μαθήματα και 337 βήματα.</b> Στο συγκεκριμένο διάστημα δεν προστέθηκαν νέες ενώσεις ή κανόνες ονοματολογίας. Τα 14 ενεργά σενάρια JSON είναι ίδια με τη βάση της Παρασκευής· οι βελτιώσεις εμφάνισης χρησιμοποιούνται μέσω του κοινού viewer.</p>
<h2>1. Ενιαία εμφάνιση ανεπτυγμένων τύπων σε 127 μόρια</h2>
<p>Αφετηρία ήταν η σύγκριση με τα προϋπάρχοντα MOL της εφαρμογής και η ομοιογένεια των δύο νεότερων αλκανίων, 2,3-διμεθυλοβουτανίου και 3-αιθυλο-2,5-διμεθυλοεξανίου. Ακολούθησαν ελεγχόμενες δοκιμές και επέκταση ανά χημική κατηγορία. Οι επιμέρους προσαρμογές διατηρούν τους μοριακούς γράφους και τις αντιστοιχίσεις προς το 3D.</p>
<table><thead><tr><th>Κατηγορία</th><th>Ανεπτυγμένοι τύποι</th></tr></thead><tbody>
<tr><td>Αλκάνια</td><td>8</td></tr><tr><td>Αλκένια</td><td>7</td></tr><tr><td>Αλκίνια</td><td>8</td></tr><tr><td>Αλκαδιένια</td><td>8</td></tr><tr><td>Αλκενίνια</td><td>7</td></tr><tr><td>Αλκοόλες</td><td>17</td></tr><tr><td>Αιθέρες</td><td>11</td></tr><tr><td>Αλδεΰδες</td><td>17</td></tr><tr><td>Κετόνες</td><td>14</td></tr><tr><td>Καρβοξυλικά οξέα</td><td>21</td></tr><tr><td>Εστέρες</td><td>9</td></tr><tr><th>Σύνολο</th><th>127</th></tr></tbody></table>
<p>Βασικές αποστάσεις σχεδίασης: <b>C–H 0,3094</b> και <b>C–C / C–O / C=O 0,6188</b>. Για C=C/C≡C η απόσταση μεταξύ των ατόμων ακολουθεί την ίδια βασική μονάδα. Στις αλκοόλες οι O–H είναι 0,3094. Οι τιμές είναι μονάδες συντεταγμένων MOL, όχι φυσικά μήκη δεσμών σε Å.</p>
<p>Η αλλαγή των MOL συνδυάζεται με κοινή βαθμονόμηση γραμμάτων, λευκών περιθωρίων και αρίθμησης, επειδή η αυτόματη κλιμάκωση του σχεδιαστή δεν διατηρεί από μόνη της την επιθυμητή αναλογία στην οθόνη. Η βαθμονόμηση δεν μετακινεί αυθαίρετα τις εγγενείς θέσεις των δεσμών του SVG.</p>
<p><b>Οι αποστάσεις δεν εξισώθηκαν τυφλά όπου θα δημιουργούσαν επικάλυψη.</b> Διατηρήθηκαν οι εγκεκριμένες οπτικά εξαιρέσεις: σύνδεσμος 0,98 στη μεγαλύτερη αλκοόλη, τρεις σύνδεσμοι 0,588 / 0,900 / 0,588 στη σύνθετη εξανο-αλδεΰδη, σύνδεσμος 0,588 στην ισοπροπυλοβουτενοδιάλη και 0,98 στην 3,4,4-τριμεθυλο-2-πεντανόνη. Οι άλλοι βασικοί δεσμοί αυτών των σχεδίων ακολουθούν την κοινή μονάδα. Πρόκειται για σχολικά διαγράμματα συνδεσιμότητας, όχι φυσικές διαμορφώσεις.</p>
<h2>2. Ομάδες O–H, αιθέρες, καρβονύλια και εστέρες</h2>
<p>Στις 17 αλκοόλες εμφανίζονται χωριστά O και H με ορατό δεσμό και στις 21 υδροξυλομάδες. Σε οκτώ παλαιότερα ανεπτυγμένα προστέθηκαν 11 ρητά H στο τέλος των λιστών, διατηρώντας τους προηγούμενους δείκτες ατόμων και δεσμών.</p>
<p>Οι 11 αιθέρες διατηρούν τις εγκεκριμένες διατάξεις των αλκυλίων. Η βαθμονόμηση περιλαμβάνει και C–O, ώστε ο διμεθυλαιθέρας, χωρίς C–C, να εμφανίζεται με την ίδια πολιτική χαρακτήρων. Διατηρήθηκαν οι μικρές αρχικές κλίσεις όπου αυτό προέβλεπε το εγκεκριμένο σχέδιο.</p>
<p>Στις 31 αλδεΰδες/κετόνες και στα 21 οξέα προσαρμόστηκαν οι αποστάσεις και οι εγκεκριμένες οριζόντιες/κατακόρυφες διακλαδώσεις. Στα 26 καρβοξύλια των οξέων το C=O είναι κατακόρυφο και το C–O–H οριζόντιο προς τα έξω. Οκτώ σύνθετες διατάξεις διατηρήθηκαν ακριβώς όπως εγκρίθηκαν στην προεπισκόπηση.</p>
<p>Στους 9 εστέρες το C=O είναι κατακόρυφο και το C–O–C οριζόντιο. Δύο παλιές διατάξεις είχαν μικρή απόκλιση από τους άξονες, έως περίπου 1,38°· διορθώθηκαν ρητά μόνο στον ανεπτυγμένο, μετά από σύγκριση πριν/μετά. Το H της ομάδας HCOO παραμένει αριστερά. Οι υπόλοιπες 2D μορφές και τα 3D αρχεία διατηρήθηκαν.</p>
<p><a href="../checks/carbonyl-uniform-20261031/comparison/index.html">Σύγκριση σύνθετων αλδεϋδών/κετονών</a> · <a href="../checks/acid-uniform-20261101/comparison/index.html">Σύγκριση οξέων</a> · <a href="../checks/ester-uniform-20261101/comparison/index.html">Σύγκριση εστέρων</a></p>
<figure><img loading="lazy" src="../checks/ester-uniform-20261101/comparison/isopropyl_ethanoate-comparison.png" alt="Πριν και μετά στον αιθανικό ισοπροπυλεστέρα, με ίδιο μέγεθος χαρακτήρων"><figcaption>Απομονωμένη σύγκριση με κοινό πλαίσιο και ίδιο μέγεθος γραμμάτων. Το αποτέλεσμα εγκρίθηκε πριν από την ενσωμάτωση.</figcaption></figure>
<h2>3. Διόρθωση της παραγωγής και μέτρησης γραμμάτων 2D</h2>
<p>Η διερεύνηση ξεκίνησε από κατακόρυφο C–H στο προπένιο που άγγιζε το C. Η αστοχία αναπαράχθηκε ήδη στην εγγενή εξαγωγή SVG: οι μετρήσεις υποεκτιμούσαν την πραγματική ζωγραφισμένη επιφάνεια του γράμματος και το λευκό φόντο δεν το κάλυπτε πλήρως.</p>
<p>Ενσωματώθηκαν ελεγμένη τοπική διανομή JSME και κοινός μηχανισμός μέτρησης/τοποθέτησης κειμένου και λευκών περιθωρίων, με αναμονή γραμματοσειρών και ασφαλή ανανέωση. Μη αναγνώσιμες ή υπερβολικά πυκνές είσοδοι απορρίπτονται ελεγχόμενα όπου οι καταγεγραμμένοι έλεγχοι το επιβάλλουν, αντί να παραμένει παλιό μόριο στην οθόνη.</p>
<p>Στην επέκταση στα οξέα διορθώθηκε επιπλέον η κοινή μεταχείριση σύνθετων ετικετών OH/HO/NH₂: το λευκό υπόβαθρο υπολογίζεται για ολόκληρη την ετικέτα. Ο τετραγωνικός κανόνας των μεμονωμένων συμβόλων δεν εφαρμόζεται πλέον στα σύνθετα αυτά κείμενα.</p>
<p><a href="../checks/svg-integration-20261031/report.html">Οπτική τεκμηρίωση 2D</a> · <a href="../checks/svg-text-prototype-20261031/comparison.html">Αρχικό πριν/μετά</a></p>
<h2>4. Στοχευμένη διόρθωση κύκλου ζωής JSmol</h2>
<p>Η ελεγχόμενη αναπαραγωγή έδειξε εργασίες επανασχεδίασης/resize να εκτελούνται μετά την καταστροφή του applet. Η τοπική διανομή ακυρώνει τις εκκρεμείς εργασίες που ανήκουν στο συγκεκριμένο applet και ελέγχει αν είναι ακόμη ενεργό πριν τις εκτελέσει, διατηρώντας τις άσχετες εργασίες της σελίδας.</p>
<p>Στις πέντε ελεγχόμενες διαδρομές, με δύο επαναλήψεις, καταγράφηκε σφάλμα σε 10/10 περιπτώσεις πριν και σε 0/10 μετά. Αυτό τεκμηριώνει τον συγκεκριμένο μηχανισμό και <b>δεν αποτελεί γενική πιστοποίηση του 3D</b>.</p>
<p><a href="../checks/jsmol-integration-20261031/report.html">Οπτική αναφορά JSmol</a> · <a href="../checks/jsmol-lifecycle-prototype-20261031/watch.html">Βίντεο πριν/μετά</a></p>
<h2>5. Έλεγχοι και όρια της τεκμηρίωσης</h2>
<ul><li>Η ενσωμάτωση γραμμάτων ελέγχθηκε αρχικά σε 422 διαθέσιμες μορφές × δύο πλάτη, δηλαδή 844 περιπτώσεις, καθώς και σε 98 καταστάσεις χειρισμών, 92 περιπτώσεις εγγενούς παραγωγού, επιλεγμένα βήματα και των 14 μαθημάτων και 18 μελλοντικές εισόδους. Η καθολική αυτή εκτέλεση προηγήθηκε των επόμενων αλλαγών ανά κατηγορία· δεν παρουσιάζεται ως ενιαία εκτέλεση της τελικής σημερινής έκδοσης.</li>
<li>Οι ακόρεστοι υδρογονάνθρακες και οι αλκοόλες ελέγχθηκαν ανά ενότητα σε ονομασίες, γράφους, μήκη, ευθυγράμμιση, zoom, αρίθμηση, επισημάνσεις και σχετικά μαθήματα. Στις αλκοόλες καταγράφηκαν 179 καταστάσεις χειρισμών και 92 καταστάσεις επανάληψης των δύο μαθημάτων.</li>
<li>Αιθέρες: 66 περιπτώσεις μορφών πριν και 66 μετά, 204 καταστάσεις χειρισμών, 22 πραγματικές φορτώσεις του σωστού μοντέλου, τρεις PNG και 58 καταστάσεις του υπάρχοντος μαθήματος 27 βημάτων.</li>
<li>Αλδεΰδες/κετόνες/οξέα: 136 περιπτώσεις μορφών πριν και 136 μετά, 194 καταστάσεις χειρισμών και 414 έλεγχοι εγγενών δεσμών/λευκών υποβάθρων. Τα έξι σχετικά μαθήματα, 157 βημάτων συνολικά, ελέγχθηκαν σε δύο πλάτη με επιστροφή/επανάληψη/έξοδο, σε 338 καταστάσεις. Ακολούθησαν 24 πρόσθετες καταστάσεις χειροκίνητης επιλογής ανεπτυγμένου και επαναφοράς μέσα στα μαθήματα.</li>
<li>Εστέρες: 54 περιπτώσεις μορφών πριν και 54 μετά, 157 καταστάσεις χειρισμών, 18 πραγματικές φορτώσεις του σωστού αρχείου 3D, 36 ενέργειες εναλλαγής και 175 έλεγχοι εγγενών δεσμών/υποβάθρων. Δύο πραγματικές εξαγωγές PNG επιθεωρήθηκαν πλήρεις.</li>
<li>Στις τελικές αυτές ενότητες έγιναν συγκρίσεις 844 περιπτώσεων του πραγματικού μηχανισμού ονοματολογίας πριν/μετά, μαζί με τις επηρεαζόμενες αντιστοιχίσεις 2D/3D. Οι ανεξάρτητοι χημικοί έλεγχοι για τα 52 καρβονυλικά/όξινα και τους 9 εστέρες περιλαμβάνουν πλήρη ισομορφισμό προς τα υπάρχοντα SDF.</li>
<li>Υπήρξε ανεξάρτητο review ανά ολοκληρωμένη ενότητα. Τα τελικά αντικείμενα αιθέρων, 52 τύπων και εστέρων δεν είχαν νέα ανοικτά ευρήματα. Οι browser εκτελέσεις αποδίδονται στον Developer· ο Reviewer ελέγχει ανεξάρτητα κώδικα/δεδομένα και τα παραδοθέντα τεκμήρια.</li></ul>
<p>Οι αριθμοί αφορούν διαφορετικές, καταγεγραμμένες εκτελέσεις και δεν αθροίζονται ως μοναδικές λειτουργίες ή ως ποσοστό αξιοπιστίας. Τα 390 CSS px είναι προσομοίωση πλάτους, όχι φυσικό κινητό. Μία αρχική αστοχία εκκίνησης του browser δοκιμών, πριν από πλοήγηση, καταγράφηκε χωριστά· δεν παρουσιάζεται ως βλάβη ή διόρθωση της εφαρμογής.</p>
<h2>6. Τοπική εκκίνηση, React και αποθήκευση</h2>
<p>Το βοηθητικό Namelecule.app στην επιφάνεια εργασίας, με εικονίδιο το μόριο του λογοτύπου, εκκινεί ή επαναχρησιμοποιεί τον τοπικό server και ανοίγει την εφαρμογή στον Firefox. Μετά από επανεκκίνηση του Mac, η εκκίνηση του server αποκατέστησε την καταγεγραμμένη αδυναμία φόρτωσης αλκοόλης· δεν χρειάστηκε αλλαγή στο ακέραιο SDF. Η ακριβής αποτυχημένη αίτηση της αρχικής εικόνας δεν είχε καταγραφεί.</p>
<p>Η δημόσια React παραμένει στην προηγούμενη δοκιμαστική της κατάσταση, χωρίς νέο build ή συγχρονισμό με τα σημερινά MOL. Η χθεσινή απομόνωση των data52/viewer52 διατηρεί τη συμβατότητά της με την ενημερωμένη κύρια. Η τοπική εργασία React διατηρείται στο χωριστό πλήρες checkpoint· δεν παρουσιάζεται ως νέα ελεγμένη δημόσια λειτουργία.</p>
<p>Διατηρούνται προηγούμενα Git checkpoints, αρχικές συμπιεσμένες πηγές και σημεία επιλεκτικής επαναφοράς. Η παρούσα αποθήκευση περιλαμβάνει πλήρες checkpoint, ZIP, Git bundle και αντίγραφα στους καθιερωμένους φακέλους αποθήκευσης και «αρχεία json», μαζί με την αναφορά, τους συνδέσμους, τα 14 ενεργά JSON και το τοπικό βοηθητικό εκκίνησης. Το αντίγραφο πηγών <b>δεν ισοδυναμεί με αυτάρκες offline πακέτο παρουσίασης</b>.</p>
<h2>7. Core και εκκρεμότητες</h2>
<p><b>Το js/mulermoc-nom-core-52.js δεν άλλαξε στην περίοδο αυτής της αναφοράς.</b> Η σύγκριση με τη βάση της Παρασκευής και την προηγούμενη δημοσίευση συμφωνεί. SHA256 <code>d2138418ff630ab77e578b80ca8ba3a10cc1b877c3ab8c0e5c2735ffcd1f24a2</code>. Οι αλλαγές αφορούν MOL/data, viewer και τις ελεγμένες τοπικές διανομές απεικόνισης· δεν εισάγουν νέους κανόνες ονοματολογίας.</p>
<div class="note"><b>Ανοικτά θέματα και όρια</b><ul><li>Στην εξαγωγή PNG ένα πολύ μεγάλο όνομα οξέος υπερβαίνει τον καμβά 1.200 px και κόβεται. Αναπαράχθηκε πριν/μετά, καταγράφηκε ως προϋπάρχον και χρειάζεται χωριστή διόρθωση.</li><li>Η παλαιότερη παρατήρηση διαφορετικού κάδρου σε επανασχεδιάσεις παραμένει ανοικτή· δεν δηλώνεται γενικά λυμένη. Η ιστορική επικάλυψη στον παλιό ισοπροπυλεστέρα δεν αναπαράχθηκε ως επαφή πραγματικών pixels στην τωρινή σύγκριση, συνεπώς δεν δηλώνεται αποδεδειγμένη διόρθωση εκείνης της συγκεκριμένης παρατήρησης.</li><li>Στον έλεγχο της δημοσίευσης καταγράφηκαν δύο προειδοποιήσεις ATOM MISMATCH από το αμετάβλητο core. Αφορούν ισοδύναμα άκρα κύριας αλυσίδας σε μία σύνθετη αλδεΰδη και στον 2,3-διμεθυλοβουτανικό ισοπροπυλεστέρα. Ο Chemistry Validator απέδειξε πλήρεις αυτομορφισμούς των SDF, μαζί με όλα τα H, που μεταφέρουν τη μία αριθμημένη αλυσίδα στην άλλη. Ο ίδιος μηχανισμός ονοματολογίας στην προηγούμενη δημοσίευση αναπαράγει τις ίδιες προειδοποιήσεις: ο διαγνωστικός έλεγχος συγκρίνει IDs ατόμων και δεν αναγνωρίζει αυτή τη συμμετρία. Δεν άλλαξε ούτε αποσιωπήθηκε εδώ· οι συγκεκριμένες προειδοποιήσεις δεν αποδεικνύουν λανθασμένη χημική αλυσίδα. Η κονσόλα δεν χαρακτηρίζεται πλήρως καθαρή.</li><li>Το j2s του JSmol παραμένει εξάρτηση CDN. Παλαιότερες δημόσιες δοκιμές είχαν εξωτερικά μηνύματα tracker/cookies· δεν χαρακτηρίζονται καθαρή κονσόλα ούτε συγχέονται με αποδεδειγμένη χημική αστοχία.</li><li>Δεν έχει πιστοποιηθεί συνολικά το Safari, φυσικό κινητό, η λειτουργία χωρίς Internet ή η πλήρης ακολουθία της παρουσίασης στο συνέδριο. Η πρόβα στον συγκεκριμένο υπολογιστή και το offline εφεδρικό πακέτο χρειάζονται ξεχωριστή προετοιμασία.</li></ul></div>
<p>Η αξιοπιστία της ροής για την παρουσίαση τον Απρίλιο 2027 παραμένει κριτήριο αποδοχής. Οι ολοκληρωμένοι έλεγχοι τεκμηριώνουν τις συνθήκες που δοκιμάστηκαν και δεν αποτελούν υπόσχεση αδιάλειπτης λειτουργίας.</p>
<p><a href="verified-facts.json">Στοιχεία και πηγές ελέγχων</a> · <a href="message-to-professor.txt">Συνοδευτικό μήνυμα</a> · <a href="CHECKPOINT">Πλήρες checkpoint κώδικα</a> · <a href="../professor-20261031/update.html">Αναφορά 31/10</a> · <a href="../professor-20261030/update.html">Αναφορά 30/10</a></p>'''
for k,v in [('WELCOME',links['welcome']),('VIEWER',links['viewer']),('CHECKPOINT',links['fullCheckpoint'])]:body=body.replace(k,v)
